local function dumpInstance(instance, log, indent)
    indent = indent or S(165)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(227) .. child.Name .. S(105)
        if child:IsA(S(161)) then
            line = line .. string.format(
                S(195),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(168)) then
            line = line .. string.format(S(174), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(223)) or child:IsA(S(5)) then
            line = line .. S(234)
        end
        log(line)
        for attrName, attrValue in pairs(child:GetAttributes()) do
            log(indent .. S(221) .. attrName .. S(40) .. tostring(attrValue))
        end
        dumpInstance(child, log, indent .. S(94))
    end
end
return dumpInstance
end
